Object.assign(copy.te,{stepCount:'దశ {step} / {total}',stepComplete:'సేవ్ అయింది',progressLoading:'సేవ్ చేసిన సమీక్ష ప్రగతి లోడ్ అవుతోంది…',progressInvalid:'సమీక్ష చెక్‌లిస్ట్ చెల్లదు. క్యూను రిఫ్రెష్ చేసి మళ్లీ ప్రయత్నించండి.',progressVersionConflict:'ఈ దరఖాస్తు మారింది. తాజా సంచిక లోడ్ అయింది; కొనసాగించే ముందు మళ్లీ సమీక్షించండి.',progressRevisionConflict:'మరో సమీక్షకుడు ఈ చెక్‌లిస్ట్ మార్చారు. తాజా ప్రగతి చూపబడింది; కొనసాగించే ముందు రిఫ్రెష్ చేయండి.',progressStepLocked:'కొనసాగించే ముందు ముందు పత్ర దశను పూర్తి చేయండి.',progressPagesUnread:'ఈ దశ సేవ్ చేసే ముందు పత్రంలోని ప్రతి పేజీని తెరవండి.',progressIncomplete:'ఆమోదానికి ముందు ప్రతి పత్ర దశను పూర్తి చేసి సేవ్ చేయండి.',progressLocked:'దరఖాస్తు సమీక్షలో లేకపోవడంతో ఈ చెక్‌లిస్ట్ లాక్ చేయబడింది.',progressSaveFailed:'చెక్‌లిస్ట్ సేవ్ కాలేదు. మీ ఎంపికలు అలాగే ఉన్నాయి; మళ్లీ ప్రయత్నించండి.',progressReload:'సేవ్ కాని తనిఖీలను తీసివేసి సేవ్ చేసిన ప్రగతిని లోడ్ చేయండి',progressRefreshBeforeSave:'ప్రగతి మరెక్కడో మారింది. మరిన్ని మార్పులు చేసే ముందు సేవ్ చేసిన ప్రగతిని రిఫ్రెష్ చేయండి.',progressAllComplete:'ప్రతి పత్ర దశ సేవ్ అయింది. ఇప్పుడు ఆమోదం అందుబాటులో ఉంది.',stepReviewChecks:'అన్ని పేజీలను సమీక్షించి, ప్రతి మాన్యువల్ తనిఖీని నమోదు చేయండి. తనిఖీలు స్వయంగా ఎంపిక కావు.',stepOpenAllPages:'తనిఖీలు నమోదు చేసే ముందు ఈ పత్రంలోని ప్రతి పేజీని తెరవండి.',stepDocumentMissing:'ఈ సమీక్ష దశకు పత్రం జత చేయబడలేదు.',stepSaveChanges:'ఈ దశ మార్పులను సేవ్ చేయండి',stepSaveNext:'సేవ్ చేసి కొనసాగండి',stepBack:'మునుపటి దశ',compareReference:'గుర్తింపు పత్రంతో పోల్చండి',decisionWithoutApproval:'ప్రతి సమీక్ష దశను పూర్తి చేసి సేవ్ చేసిన తర్వాతే ఆమోదం అందుబాటులో ఉంటుంది.',progressUnsaved:'చెక్‌లిస్ట్ మార్పులు సేవ్ కాలేదు. ఆమోదానికి ముందు వాటిని సేవ్ చేయండి.',privateFile:'ప్రైవేట్ ఫైల్'});
Object.assign(copy.hi,{stepCount:'चरण {step} / {total}',stepComplete:'सहेजा गया',progressLoading:'सहेजी गई समीक्षा प्रगति लोड हो रही है…',progressInvalid:'समीक्षा चेकलिस्ट अमान्य है। कतार रीफ़्रेश करके फिर कोशिश करें।',progressVersionConflict:'यह आवेदन बदल गया है। नवीनतम संस्करण लोड हुआ; आगे बढ़ने से पहले समीक्षा करें।',progressRevisionConflict:'दूसरे समीक्षक ने यह चेकलिस्ट बदली। नवीनतम प्रगति दिख रही है; आगे बढ़ने से पहले रीफ़्रेश करें।',progressStepLocked:'आगे बढ़ने से पहले पिछला दस्तावेज़ चरण पूरा करें।',progressPagesUnread:'इस चरण को सहेजने से पहले दस्तावेज़ के हर पृष्ठ को खोलें।',progressIncomplete:'स्वीकृति से पहले हर दस्तावेज़ चरण पूरा करके सहेजें।',progressLocked:'आवेदन समीक्षा में नहीं है, इसलिए यह चेकलिस्ट लॉक है।',progressSaveFailed:'चेकलिस्ट सहेजी नहीं जा सकी। आपकी पसंद मौजूद है; फिर कोशिश करें।',progressReload:'बिना सहेजी जांच हटाकर सहेजी प्रगति लोड करें',progressRefreshBeforeSave:'प्रगति कहीं और बदली गई। आगे संपादन से पहले सहेजी प्रगति रीफ़्रेश करें।',progressAllComplete:'हर दस्तावेज़ चरण सहेजा गया। अब स्वीकृति उपलब्ध है।',stepReviewChecks:'हर पृष्ठ देखें, फिर नीचे हर मैन्युअल जांच दर्ज करें। जांच अपने आप नहीं चुनी जातीं।',stepOpenAllPages:'जांच दर्ज करने से पहले इस दस्तावेज़ का हर पृष्ठ खोलें।',stepDocumentMissing:'इस समीक्षा चरण में कोई दस्तावेज़ संलग्न नहीं है।',stepSaveChanges:'इस चरण के बदलाव सहेजें',stepSaveNext:'सहेजें और आगे बढ़ें',stepBack:'पिछला चरण',compareReference:'पहचान दस्तावेज़ से तुलना करें',decisionWithoutApproval:'हर समीक्षा चरण पूरा करके सहेजने के बाद ही स्वीकृति उपलब्ध होगी।',progressUnsaved:'चेकलिस्ट के बदलाव सहेजे नहीं गए हैं। स्वीकृति से पहले उन्हें सहेजें।',privateFile:'निजी फ़ाइल'});
const text=k=>k==='fileHelp'?`${copy[state.lang]?.[k]||copy.en[k]} ${viewerCopy[state.lang]?.pdfLimit||viewerCopy.en.pdfLimit}`:copy[state.lang]?.[k]||copy.en[k]||viewerCopy[state.lang]?.[k]||viewerCopy.en[k]||k;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const isStaff=()=>state.user?.access?.is_staff===true||['staff','admin'].includes(state.user?.role);
  const canReview=()=>isStaff()&&(state.user?.access?.staff_capabilities||[]).includes('verify.review');
  const privateFileLabel=()=>state.lang==='te'?'ప్రైవేట్ ఫైల్':state.lang==='hi'?'निजी फ़ाइल':'Private file';
  const expiryLabel=()=>state.lang==='te'?'సమీక్ష గడువు':state.lang==='hi'?'समीक्षा की अवधि':'Review expires';
  const formatExpiry=value=>{const date=new Date(value);return Number.isNaN(date.valueOf())?String(value):new Intl.DateTimeFormat(state.lang==='te'?'te-IN':state.lang==='hi'?'hi-IN':'en-IN',{dateStyle:'medium'}).format(date);};
  const statusLabel=v=>{const labels={not_started:['Not started','ప్రారంభం కాలేదు','शुरू नहीं हुआ'],draft:['Draft','చిత్తుప్రతి','मसौदा'],submitted:['Submitted','సమర్పించబడింది','जमा हुआ'],needs_changes:['Changes requested','మార్పులు కోరబడ్డాయి','बदलाव मांगे गए'],rejected:['Declined','తిరస్కరించబడింది','अस्वीकृत'],approved:['Reviewed','సమీక్షించబడింది','समीक्षा की गई'],revoked:['Review revoked','సమీక్ష రద్దు','समीक्षा रद्द']};const index=['en','te','hi'].indexOf(state.lang);return labels[v]?.[index]||(state.lang==='te'?'ఉపసంహరించబడింది':state.lang==='hi'?'वापस लिया गया':'Withdrawn');};
  const appFor=view=>cache.get(view)?.application||null;
  const reqFor=view=>cache.get(view)?.requirements||{};
  const documents=a=>a?.documents||[];
  const previewKey=(a,d)=>`${a.id}:${a.version}:${d.id}`;
  function hasViewedAllPages(a,d){const value=openedPages.get(previewKey(a,d));return Boolean(value&&value.pageCount>0&&value.pages.size===value.pageCount);}
  const progressKey=a=>`${a.id}:${a.version}`;
  const progressEntry=a=>reviewProgress.get(progressKey(a));
  const progressError=error=>({review_progress_invalid:'progressInvalid',review_progress_version_conflict:'progressVersionConflict',review_progress_revision_conflict:'progressRevisionConflict',review_progress_step_locked:'progressStepLocked',review_progress_documents_unread:'progressPagesUnread',review_progress_incomplete:'progressIncomplete',review_progress_locked:'progressLocked'}[error?.code]||'progressSaveFailed');
  function readStepValues(form){return Object.fromEntries(identityReviewSteps.find(x=>x.key===form.dataset.ifStep).checks.map(k=>[k,Boolean(form.elements[k]?.checked)]));}
  function canSaveReviewStep(app,key,values){const record=progressEntry(app),step=record?.data?.steps?.find(x=>x.key===key),cfg=identityReviewSteps.find(x=>x.key===key),doc=documents(app).find(x=>x.id===step?.document_id),saved=step?.checks||{},complete=step?.complete===true,read=complete||Boolean(doc&&hasViewedAllPages(app,doc)),allChecked=Boolean(cfg&&cfg.checks.every(k=>values?.[k]===true)),changed=Boolean(cfg&&cfg.checks.some(k=>(values?.[k]===true)!==(saved[k]===true)));return read&&(allChecked||(complete&&changed))&&!record?.stale;}
  function reviewProgressReady(app){const record=progressEntry(app);if(!record?.data?.ready_for_approval||record.loading||record.stale)return false;return identityReviewSteps.every(cfg=>{const server=record.data.steps.find(x=>x.key===cfg.key),local=reviewStepDrafts.get(`${progressKey(app)}:${cfg.key}`);return server?.complete===true&&(!local||cfg.checks.every(k=>(local[k]===true)===(server.checks?.[k]===true)));});}
  function captureReviewStep(form){const app=(cache.get('identity-review')?.applications||[]).find(x=>x.id===form.dataset.ifId);if(!app)return;const key=progressKey(app),step=form.dataset.ifStep,draftKey=`${key}:${step}`,values=readStepValues(form);reviewStepDrafts.set(draftKey,values);const button=form.querySelector('[data-if-save-step]');if(button)button.disabled=busy||!canSaveReviewStep(app,step,values);const review=form.closest('[data-if-application]')?.querySelector('form[data-if-form="review-decision"]'),select=review?.elements.decision;if(select){const approved=select.querySelector('option[value="approved"]'),ready=reviewProgressReady(app);if(approved)approved.disabled=!ready;if(!ready&&select.value==='approved')select.value='needs_changes';const notice=review.querySelector('[data-if-progress-dirty]');if(notice)notice.hidden=ready;}}
  async function loadReviewProgress(app,force=false,options={}){if(!canReview()||app.status!=='submitted')return;const key=progressKey(app),old=reviewProgress.get(key);if(old?.loading||(!force&&(old?.data||old?.attempted)))return;const rev=epoch,account=state.user?.id,view=route;reviewProgress.set(key,{...old,loading:true,attempted:true,error:options.notice||''});try{const data=await api(`/api/identity_review_progress?application_id=${encodeURIComponent(app.id)}`);if(epoch!==rev||state.user?.id!==account||route!==view)return;if(data.application_id!==app.id||data.application_version!==app.version||!Number.isInteger(data.revision)||!Array.isArray(data.steps)){const error=Object.assign(new Error(text('progressVersionConflict')),{code:'review_progress_version_conflict',status:409});throw error;}reviewProgress.set(key,{data,loading:false,error:options.notice||'',stale:options.stale===true});if(!reviewActive.has(key))reviewActive.set(key,data.current_step||identityReviewSteps.at(-1).key);}catch(error){if(epoch!==rev||state.user?.id!==account||route!==view)return;reviewProgress.set(key,{...old,loading:false,attempted:true,error:text(progressError(error)),stale:options.stale===true});if(error.status===401)await expire();else if(error.code==='identity_forbidden')await clearReviewAccess();else if(error.code==='review_progress_version_conflict'){const entry=cache.get(view)||{};cache.set(view,{...entry,notice:text('progressVersionConflict')});void load(view,true);}}finally{if(epoch===rev&&route===view&&state.user?.id===account)render();}}
  function preloadReviewProgress(apps,force=false){for(const app of apps||[])if(app.status==='submitted')void loadReviewProgress(app,force);}
